{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "label_pos",
  "per_column": [
    {
      "name": "negative_word_count",
      "role": "predictor",
      "rationale": "Count of negative-sentiment words in the review text; lies outside the label, is knowable before the outcome, and plausibly carries strong signal about negative satisfaction. A legitimate lexical predictor."
    },
    {
      "name": "exclamation_count",
      "role": "predictor",
      "rationale": "Punctuation-based intensity feature derived from text, independent of the label. Weak-to-moderate but plausible signal (emotional emphasis can associate with polarity), not leakage or restatement."
    },
    {
      "name": "caps_word_count",
      "role": "predictor",
      "rationale": "All-caps word count captures emphasis/shouting, a stylistic cue that can correlate with strong (often negative) sentiment. Outside the focus and non-leaky; modest predictive value."
    },
    {
      "name": "negation_intensifier_count",
      "role": "predictor",
      "rationale": "Counts negations/intensifiers, which modulate sentiment polarity and intensity; a legitimate text-derived predictor that plausibly helps distinguish negative reviews without restating the label."
    }
  ],
  "n_predictors": 4,
  "predictive_utility": 0.55,
  "rationale": "All four columns are text-derived features that lie outside the focus variable, are knowable prior to the outcome (no leakage), and none restate label_pos. negative_word_count is the strongest signal for the negative-satisfaction target; negation_intensifier_count adds polarity-modulating signal; exclamation_count and caps_word_count contribute weaker stylistic emphasis cues. As a set they give moderate genuine predictive leverage beyond review_text alone, though they are relatively generic lexical/stylistic counts rather than richly engineered semantic features, capping their utility."
}
